{
  "project_id": "0943e60317404ca9ae95",
  "query": "select n.nspname as schema_name, c.relname as table_name, c.relrowsecurity as rls_enabled, c.relforcerowsecurity as rls_forced, count(p.policyname) as policy_count from pg_class c join pg_namespace n on n.oid=c.relnamespace left join pg_policies p on p.schemaname=n.nspname and p.tablename=c.relname where c.relkind in ('r','p') and n.nspname not in ('pg_catalog','information_schema') group by n.nspname,c.relname,c.relrowsecurity,c.relforcerowsecurity order by 1,2;"
}

